use std::collections::{BTreeMap,BTreeSet,VecDeque};
use crate::molecule::{Molecule,Elements,Error};
fn edge_set(m:&Molecule,ring:&[usize])->BTreeSet<usize>{
    (0..ring.len()).map(|i|m.bond(ring[i],ring[(i+1)%ring.len()]).unwrap()).collect()
}
pub fn detect(m:&mut Molecule){
    let n=m.atoms.len();
    let mut candidates=Vec::new();
    let mut seen=BTreeSet::new();
    for root in 0..n{
        let mut parent=vec![None;n];
        let mut visited=vec![false;n];
        visited[root]=true;
        let mut queue=VecDeque::new();
        queue.push_back(root);
        while let Some(a)=queue.pop_front(){
            for &(b,_)in &m.neighbors[a]{
                if !visited[b]{
                    visited[b]=true;
                    parent[b]=Some(a);
                    queue.push_back(b);
                }
            }
        }
        let path=|mut x:usize|{
            let mut p=vec![x];
            while let Some(a)=parent[x]{
                p.push(a);
                x=a;
            }
            p
        };
        for bond in &m.bonds{
            let(x,y)=(bond.a,bond.b);
            if parent[x]==Some(y)||parent[y]==Some(x){
                continue;
            }
            let(mut a,mut b)=(path(x),path(y));
            if a.iter().any(|v|*v!=root&&b.contains(v)){
                continue;
            }
            a.reverse();
            b.pop();
            a.extend(b);
            let edges=edge_set(m,&a);
            if seen.insert(edges.clone()){
                candidates.push((a,edges));
            }
        }
    }
    candidates.sort_by_key(|(r,_)|r.len());
    let mut basis:BTreeMap<usize,BTreeSet<usize>>=BTreeMap::new();
    let mut selected=Vec::new();
    for(ring,edges)in candidates{
        let mut vector=edges.clone();
        while let Some(&pivot)=vector.iter().next_back(){
            if let Some(b)=basis.get(&pivot){
                vector=vector.symmetric_difference(b).copied().collect();
            }else{
                basis.insert(pivot,vector);
                selected.push(ring);
                break;
            }
        }
    }
    for r in &mut selected{
        let k=r.iter().enumerate().min_by_key(|(_,a)|**a).unwrap().0;
        r.rotate_left(k);
        if r[1]>r[r.len()-1]{
            r[1..].reverse();
        }
    }
    selected.sort_by(|a,b|a.len().cmp(&b.len()).then(a.cmp(b)));
    for r in &selected{
        for e in edge_set(m,r){
            m.bonds[e].ring=true;
        }
    }
    m.rings=selected;
}
fn matching(m:&Molecule,system:&BTreeSet<usize>,paired:&mut BTreeMap<usize,usize>)->bool{
    let u=match system.iter().find(|u|!paired.contains_key(*u)){
        Some(&u)=>u,None=>return true
    };
    for &(v,e)in &m.neighbors[u]{
        if system.contains(&v)&&!paired.contains_key(&v)&&m.bonds[e].kind==4{
            paired.insert(u,v);
            paired.insert(v,u);
            if matching(m,system,paired){
                return true;
            }
            paired.remove(&u);
            paired.remove(&v);
        }
    }
    false
}
pub fn kekulize(m:&mut Molecule,elements:&Elements)->Result<(),Error>{
    let mut remaining:BTreeSet<_>=(0..m.atoms.len()).filter(|&i|m.needs_pi(i,elements,true)).collect();
    let mut paired=BTreeMap::new();
    while let Some(&start)=remaining.iter().next(){
        let mut system=BTreeSet::new();
        let mut stack=vec![start];
        remaining.remove(&start);
        while let Some(a)=stack.pop(){
            system.insert(a);
            for &(b,e)in &m.neighbors[a]{
                if m.bonds[e].kind==4&&remaining.remove(&b){
                    stack.push(b);
                }
            }
        }
        if !matching(m,&system,&mut paired){
            return Err(Error::new("kekulization failed",m.atoms[*system.iter().next().unwrap()].column));
        }
    }
    for b in &mut m.bonds{
        b.multiplicity=if b.kind==4{
            if paired.get(&b.a)==Some(&b.b){
                2
            }else{
                1
            }
        }else{
            b.kind as usize
        };
    }
    Ok(())
}

use std::collections::BTreeSet;
use crate::molecule::{Molecule,Error,Elements};
#[derive(Clone)] pub enum Matcher{
    Any,
    Aliphatic,
    Aromatic,
    List(Vec<(String,bool)>)
}
pub fn pattern_atom(s:&[u8],column:usize)->Result<(Matcher,usize),Error>{
    match s[0]{
        b'*'=>Ok((Matcher::Any,1)),b'A'=>Ok((Matcher::Aliphatic,1)),b'a'=>Ok((Matcher::Aromatic,1)),b'['=>{
            let end=s.iter().position(|&c|c==b']').ok_or_else(||Error::new("unclosed bracket",column))?;
            let mut list=Vec::new();
            for part in s[1..end].split(|&c|c==b','){
                let(element,aromatic,n)=crate::smiles_parser::organic(part).ok_or_else(||Error::new("bad bracket atom",column))?;
                if n!=part.len(){
                    return Err(Error::new("bad bracket atom",column));
                }
                list.push((element,aromatic));
            }
            Ok((Matcher::List(list),end+1))
        },_=>{
            let(e,a,n)=crate::smiles_parser::organic(s).ok_or_else(||Error::new("unexpected character",column))?;
            Ok((Matcher::List(vec![(e,a)]),n))
        }
    }
}
pub struct Pattern{
    pub graph:Molecule,
    pub atoms:Vec<Matcher>
}
impl Pattern{
    pub fn parse(s:&str,e:&Elements)->Result<Self,Error>{
        let p=crate::smiles_parser::parse(s,e,true)?;
        Ok(Self{
            graph:p.molecule,
            atoms:p.matchers
        })
    }
    pub fn molecule(m:&Molecule)->Self{
        Self{
            graph:m.clone(),
            atoms:m.atoms.iter().map(|a|Matcher::List(vec![(a.element.clone(),a.aromatic)])).collect()
        }
    }
}
pub struct Matches{
    pub count:usize,
    pub unique:usize,
    pub first:Vec<usize>
}
pub fn embeddings(pattern:&Pattern,m:&Molecule)->Matches{
    fn visit(p:&Pattern,m:&Molecule,map:&mut Vec<usize>,used:&mut BTreeSet<usize>,count:&mut usize,sets:&mut BTreeSet<Vec<usize>>,first:&mut Vec<usize>){
        let a=map.len();
        if a==p.atoms.len(){
            *count+=1;
            if first.is_empty(){
                *first=map.iter().map(|v|v+1).collect();
            }
            let mut set=map.clone();
            set.sort();
            sets.insert(set);
            return;
        }
        for b in 0..m.atoms.len(){
            if used.contains(&b){
                continue;
            }
            let atom=&m.atoms[b];
            let matches=match &p.atoms[a]{
                Matcher::Any=>true,Matcher::Aliphatic=>!atom.aromatic,Matcher::Aromatic=>atom.aromatic,Matcher::List(list)=>list.iter().any(|(e,r)|*e==atom.element&&*r==atom.aromatic)
            };
            if !matches{
                continue;
            }
            let bonds=p.graph.neighbors[a].iter().filter(|&&(v,_)|v<a).all(|&(v,e)|m.bond(b,map[v]).map_or(false,|f|match p.graph.bonds[e].kind{
                0=>m.bonds[f].kind==1||m.bonds[f].kind==4,5=>true,k=>m.bonds[f].kind==k
            }));
            if bonds{
                used.insert(b);
                map.push(b);
                visit(p,m,map,used,count,sets,first);
                map.pop();
                used.remove(&b);
            }
        }
    }
    let(mut count,mut first,mut sets)=(0,Vec::new(),BTreeSet::new());
    visit(pattern,m,&mut Vec::new(),&mut BTreeSet::new(),&mut count,&mut sets,&mut first);
    Matches{
        count,
        unique:sets.len(),
        first
    }
}
pub struct Fingerprint{
    pub bits:BTreeSet<usize>,
    pub paths:usize
}
pub fn fingerprint(m:&Molecule,e:&Elements)->Fingerprint{
    fn walk(m:&Molecule,codes:&[usize],path:&mut Vec<usize>,hash:usize,result:&mut Fingerprint){
        result.paths+=1;
        result.bits.insert(hash%1024);
        if path.len()==6{
            return;
        }
        let a=*path.last().unwrap();
        for &(b,e)in &m.neighbors[a]{
            if !path.contains(&b){
                let h=((hash*31+m.bonds[e].kind as usize)%1000003*31+codes[b])%1000003;
                path.push(b);
                walk(m,codes,path,h,result);
                path.pop();
            }
        }
    }
    let codes:Vec<_>=m.atoms.iter().enumerate().map(|(i,a)|16*e[&a.element].number as usize+8*usize::from(a.aromatic)+m.neighbors[i].len()).collect();
    let mut result=Fingerprint{
        bits:BTreeSet::new(),
        paths:0
    };
    for i in 0..m.atoms.len(){
        walk(m,&codes,&mut vec![i],codes[i],&mut result);
    }
    result
}
pub fn similarity(a:&Fingerprint,b:&Fingerprint)->(usize,usize){
    let common=a.bits.intersection(&b.bits).count();
    (common,a.bits.len()+b.bits.len()-common)
}

use std::collections::BTreeMap;
use crate::molecule::{Atom,Bond,Molecule,Elements,Error};
use crate::search::{Matcher,pattern_atom};
pub struct Parsed{
    pub molecule:Molecule,
    pub matchers:Vec<Matcher>
}
pub fn organic(text:&[u8])->Option<(String,bool,usize)>{
    if text.starts_with(b"Cl"){
        return Some(("Cl".into(),false,2));
    }
    if text.starts_with(b"Br"){
        return Some(("Br".into(),false,2));
    }
    let c=*text.first()?;
    if b"BCNOPSFI".contains(&c){
        Some(((c as char).to_string(),false,1))
    }else if b"bcnops".contains(&c){
        Some(((c as char).to_ascii_uppercase().to_string(),true,1))
    }else{
        None
    }
}
fn atom(text:&[u8],column:usize,elements:&Elements)->Result<(Atom,usize),Error>{
    if text[0]!=b'['{
        let(element,aromatic,n)=organic(text).ok_or_else(||Error::new("unexpected character",column))?;
        return Ok((Atom{
            element,
            aromatic,
            mass:0,
            charge:0,
            hydrogens:0,
            bracket:false,
            column
        },n));
    }
    let end=text.iter().position(|&c|c==b']').ok_or_else(||Error::new("unclosed bracket",column))?;
    let s=&text[1..end];
    let mut i=0;
    while i<s.len()&&s[i].is_ascii_digit(){
        i+=1;
    }
    if i>=4||i>0&&s[0]==b'0'{
        return Err(Error::new("bad bracket atom",column));
    }
    let mass=if i==0{
        0
    }else{
        std::str::from_utf8(&s[..i]).unwrap().parse().unwrap()
    };
    let(element,aromatic)=if i==s.len(){
        return Err(Error::new("bad bracket atom",column));
    }else if b"bcnops".contains(&s[i]){
        let e=(s[i]as char).to_ascii_uppercase().to_string();
        i+=1;
        (e,true)
    }else if s[i].is_ascii_uppercase(){
        let one=(s[i]as char).to_string();
        if i+1<s.len()&&s[i+1].is_ascii_lowercase(){
            let two=std::str::from_utf8(&s[i..i+2]).unwrap();
            if elements.contains_key(two){
                i+=2;
                (two.to_string(),false)
            }else if elements.contains_key(&one){
                i+=1;
                (one,false)
            }else{
                return Err(Error::new("unknown element",column));
            }
        }else if elements.contains_key(&one){
            i+=1;
            (one,false)
        }else{
            return Err(Error::new("unknown element",column));
        }
    }else{
        return Err(Error::new("bad bracket atom",column));
    };
    if i<s.len()&&s[i]==b'@'{
        i+=1;
        if i<s.len()&&s[i]==b'@'{
            i+=1;
        }
    }
    let mut hydrogens=0;
    if i<s.len()&&s[i]==b'H'{
        hydrogens=1;
        i+=1;
        if i<s.len()&&s[i].is_ascii_digit(){
            hydrogens=(s[i]-b'0')as usize;
            i+=1;
        }
    }
    let mut charge=0;
    if i<s.len()&&(s[i]==b'+'||s[i]==b'-'){
        let sign=if s[i]==b'+'{
            1
        }else{
            -1
        };
        i+=1;
        let amount=if i<s.len()&&(b'1'..=b'9').contains(&s[i]){
            let n=(s[i]-b'0')as i32;
            i+=1;
            n
        }else{
            1
        };
        charge=sign*amount;
    }
    if i!=s.len(){
        return Err(Error::new("bad bracket atom",column));
    }
    Ok((Atom{
        element,
        aromatic,
        mass,
        charge,
        hydrogens,
        bracket:true,
        column
    },end+1))
}
fn symbol(c:u8,pattern:bool)->Option<u8>{
    match c{
        b'-'=>Some(1),b'='=>Some(2),b'#'=>Some(3),b':'=>Some(4),b'~'if pattern=>Some(5),b'/'|b'\\'if !pattern=>Some(1),_=>None
    }
}
fn add(m:&mut Molecule,a:usize,b:usize,kind:u8){
    m.bonds.push(Bond{
        a:a.min(b),
        b:a.max(b),
        kind,
        multiplicity:0,
        ring:false
    });
}
pub fn parse(text:&str,elements:&Elements,pattern:bool)->Result<Parsed,Error>{
    let s=text.as_bytes();
    let mut m=Molecule::default();
    let mut matchers=Vec::new();
    let mut current=None;
    let mut pending=None;
    let mut branches=Vec::new();
    let mut rings:BTreeMap<usize,(usize,Option<(u8,usize)>,usize)>=BTreeMap::new();
    let mut i=0;
    while i<s.len(){
        let c=s[i];
        let column=i+1;
        if let Some(kind)=symbol(c,pattern){
            if current.is_none()||pending.is_some(){
                return Err(Error::new("misplaced bond",column));
            }
            pending=Some((kind,column));
            i+=1;
        }else if c==b'('{
            if current.is_none()||pending.is_some()||i>0&&s[i-1]==b'('{
                return Err(Error::new("misplaced branch",column));
            }
            branches.push((current.unwrap(),column));
            i+=1;
        }else if c==b')'{
            if branches.is_empty(){
                return Err(Error::new("unmatched parenthesis",column));
            }
            if let Some((_,col))=pending{
                return Err(Error::new("dangling bond",col));
            }
            if i>0&&s[i-1]==b'('{
                return Err(Error::new("empty branch",column));
            }
            current=Some(branches.pop().unwrap().0);
            i+=1;
        }else if c.is_ascii_digit()||c==b'%'{
            let a=current.ok_or_else(||Error::new("misplaced ring closure",column))?;
            let number;
            if c==b'%'{
                if i+2>=s.len()||!s[i+1].is_ascii_digit()||!s[i+2].is_ascii_digit(){
                    return Err(Error::new("bad ring number",column));
                }
                number=((s[i+1]-b'0')as usize)*10+(s[i+2]-b'0')as usize;
                i+=3;
            }else{
                number=(c-b'0')as usize;
                i+=1;
            }
            let closing=pending.take();
            if let Some((opening,kind,_))=rings.remove(&number){
                if opening==a{
                    return Err(Error::new("self bond",column));
                }
                if let(Some((x,_)),Some((y,_)))=(kind,closing){
                    if x!=y{
                        return Err(Error::new("ring bond mismatch",column));
                    }
                }
                if m.bonds.iter().any(|b|b.a==opening.min(a)&&b.b==opening.max(a)){
                    return Err(Error::new("duplicate bond",column));
                }
                add(&mut m,opening,a,closing.or(kind).map_or(0,|v|v.0));
            }else{
                rings.insert(number,(a,closing,column));
            }
        }else{
            let(atom,n)=if pattern{
                let(matcher,n)=pattern_atom(&s[i..],column)?;
                matchers.push(matcher);
                (Atom{
                    element:String::new(),
                    aromatic:false,
                    mass:0,
                    charge:0,
                    hydrogens:0,
                    bracket:false,
                    column
                },n)
            }else{
                atom(&s[i..],column,elements)?
            };
            let next=m.atoms.len();
            m.atoms.push(atom);
            if let Some(a)=current{
                add(&mut m,a,next,pending.map_or(0,|v|v.0));
            }
            current=Some(next);
            pending=None;
            i+=n;
        }
    }
    if let Some((_,column))=pending{
        return Err(Error::new("dangling bond",column));
    }
    if let Some(&(_,column))=branches.first(){
        return Err(Error::new("unmatched parenthesis",column));
    }
    if let Some(column)=rings.values().map(|v|v.2).min(){
        return Err(Error::new("unclosed ring",column));
    }
    m.rebuild();
    Ok(Parsed{
        molecule:m,
        matchers
    })
}
